// Scale routes to bubble radius: Chart.js uses r (radius in pixels)
// routes range: 95–370. Map to r: 7–28
function routesToRadius(routes) {
  const minR = 95, maxR = 370;
  const minPx = 7, maxPx = 26;
  return minPx + ((routes - minR) / (maxR - minR)) * (maxPx - minPx);
}

